<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\AuditLog; use App\Models\User; use Illuminate\Http\Request;
class UserController extends Controller { private function allow(){abort_unless(request()->user()->role==='super_admin',403);} public function index(){$this->allow();return view('admin.users.index',['users'=>User::orderBy('name')->get()]);} public function create(){$this->allow();return view('admin.users.form',['user'=>new User]);} public function store(Request $r){$this->allow();$d=$r->validate(['name'=>'required|max:255','email'=>'required|email|unique:users,email','password'=>'required|min:12|confirmed','role'=>'required|in:super_admin,admin,editor,writer']);$user=User::create($d);AuditLog::record('user.created',$user);return redirect()->route('admin.users.index');} public function edit(User $user){$this->allow();return view('admin.users.form',['user'=>$user]);} public function update(Request $r,User $user){$this->allow();$d=$r->validate(['name'=>'required|max:255','email'=>'required|email|unique:users,email,'.$user->id,'password'=>'nullable|min:12|confirmed','role'=>'required|in:super_admin,admin,editor,writer']);if(blank($d['password']))unset($d['password']);$user->update($d);AuditLog::record('user.updated',$user);return redirect()->route('admin.users.index');} public function destroy(User $user){$this->allow();abort_if($user->is(request()->user()),422);$user->delete();AuditLog::record('user.deleted',$user);return back();} }